let contentState=null,drafts={},activeGroup='general',activePanel='portfolio',uploadsPending=0;
const panels={portfolio:'#dashboard',content:'#content-panel',contact:'#contact-panel',account:'#account-panel'};
function studioReady(){document.body.dataset.adminState='ready';$('#admin-sidebar').hidden=false;switchPanel(activePanel)}
function studioLogin(){delete document.body.dataset.adminState;$('#admin-sidebar').hidden=true;Object.values(panels).forEach(selector=>$(selector).hidden=true);$('#cms-status').textContent='';contentState=null;drafts={};activePanel='portfolio'}
document.addEventListener('admin-ready',studioReady);document.addEventListener('admin-logout',studioLogin);
function dirty(){return contentState&&Object.keys(drafts).some(key=>drafts[key]!==contentState.data[key])}
addEventListener('beforeunload',event=>{if(dirty()){event.preventDefault();event.returnValue=''}});
async function loadWebsiteContent(force=false){if(contentState&&!force)return;const data=await api('content');contentState=data;drafts={...data.data};renderContentTabs()}
async function switchPanel(panel){activePanel=panel;Object.entries(panels).forEach(([key,selector])=>$(selector).hidden=key!==panel);document.querySelectorAll('[data-admin-panel]').forEach(button=>{const active=button.dataset.adminPanel===panel;button.classList.toggle('active',active);button.setAttribute('aria-current',active?'page':'false')});$('#cms-status').textContent='';if(panel==='content'||panel==='contact'){try{await loadWebsiteContent();renderContentForm(panel==='contact'?'contact':activeGroup)}catch(e){$('#cms-status').textContent=e.message}}}
document.querySelectorAll('[data-admin-panel]').forEach(button=>button.onclick=()=>switchPanel(button.dataset.adminPanel));
$('#sidebar-categories').onclick=()=>$('#categories-open').click();
$('#account-logout').onclick=()=>$('#logout').click();
function renderContentTabs(){const tabs=$('#content-tabs');tabs.replaceChildren();for(const group of contentState.schema.groups.filter(g=>g.key!=='contact')){const button=document.createElement('button');button.type='button';button.textContent=group.label;button.classList.toggle('active',group.key===activeGroup);button.onclick=()=>{activeGroup=group.key;renderContentTabs();renderContentForm(group.key)};tabs.append(button)}}
function renderContentForm(groupKey){const host=$(groupKey==='contact'?'#contact-editor':'#content-editor');host.replaceChildren();const group=contentState.schema.groups.find(g=>g.key===groupKey);const form=document.createElement('form');form.className='content-form';const heading=document.createElement('h2');heading.textContent=group.label;const intro=document.createElement('p');intro.className='hint';intro.textContent=group.description;const fields=document.createElement('div');fields.className='cms-fields';const error=document.createElement('p');error.className='cms-error';error.setAttribute('role','alert');const message=document.createElement('span');message.textContent='แก้ไขแล้วกดบันทึก เพื่ออัปเดตหน้าเว็บไซต์';const submit=document.createElement('button');submit.className='primary';submit.type='submit';submit.textContent='บันทึกส่วนนี้';
 for(const field of contentState.schema.fields.filter(f=>f.group===groupKey)){const wrap=document.createElement('div');wrap.className='cms-field'+(['textarea','image'].includes(field.type)?' wide':'');const label=document.createElement('label');label.textContent=field.label;
  if(field.type==='image'){const box=document.createElement('div');box.className='cms-image';const image=document.createElement('img');image.src=drafts[field.key];image.alt=field.label;const input=document.createElement('input');input.type='file';input.accept='image/jpeg,image/png,image/webp';input.setAttribute('aria-label','เปลี่ยน'+field.label);const status=document.createElement('span');status.className='hint';input.onchange=async()=>{const file=input.files[0];if(!file)return;uploadsPending++;submit.disabled=true;status.textContent='กำลังเตรียมรูป…';error.textContent='';try{const uploaded=await api('upload','POST',{image:await prepareImage(file)});drafts[field.key]=uploaded.full_url;image.src=uploaded.full_url;status.textContent='รูปพร้อมแล้ว กดบันทึกเพื่อใช้บนเว็บไซต์'}catch(e){error.textContent=e.message;status.textContent='';input.value=''}finally{uploadsPending--;submit.disabled=uploadsPending>0}};box.append(image,input,status);wrap.append(label,box)
  }else{const input=document.createElement(field.type==='textarea'?'textarea':'input');input.name=field.key;input.id='cms-'+field.key;label.htmlFor=input.id;input.value=drafts[field.key]||'';input.maxLength=field.max;input.required=field.required;if(field.type==='textarea')input.rows=field.max>1000?6:3;else input.type=field.type==='url'?'url':field.type==='phone'?'tel':'text';input.oninput=()=>{drafts[field.key]=input.value;message.textContent='มีการแก้ไขที่ยังไม่ได้บันทึก'};label.append(input);wrap.append(label)}fields.append(wrap)
 }
 const actions=document.createElement('div');actions.className='content-actions';actions.append(message,submit);form.append(heading,intro,fields,error,actions);form.onsubmit=async event=>{event.preventDefault();if(uploadsPending){error.textContent='กรุณารอให้อัปโหลดรูปเสร็จก่อน';return}submit.disabled=true;error.textContent='';try{const values={};for(const field of contentState.schema.fields.filter(f=>f.group===groupKey))values[field.key]=drafts[field.key];const result=await api('content','PUT',{group:groupKey,version:contentState.version,values});contentState.data=result.data;contentState.version=result.version;for(const key of Object.keys(values))drafts[key]=result.data[key];message.textContent='บันทึกแล้ว หน้าเว็บไซต์ใช้ข้อมูลล่าสุด';$('#cms-status').textContent='บันทึก '+group.label+' เรียบร้อยแล้ว'}catch(e){error.textContent=e.message}finally{submit.disabled=false}};host.append(form)
}
document.querySelectorAll('.reload-content').forEach(button=>button.onclick=async()=>{if(dirty()&&!confirm('มีข้อมูลที่ยังไม่ได้บันทึก ต้องการทิ้งการแก้ไขและโหลดใหม่หรือไม่?'))return;button.disabled=true;try{await loadWebsiteContent(true);renderContentForm(activePanel==='contact'?'contact':activeGroup);$('#cms-status').textContent='โหลดข้อมูลล่าสุดแล้ว'}catch(e){$('#cms-status').textContent=e.message}finally{button.disabled=false}});
if(!$('#dashboard').hidden)studioReady();
